// CSD_RATIONALE_BEGIN
// Strategy: GSM-Symbolic step-by-step math solver using GenerateWithPrefixAndManagedSpan.
// We prepend task guidance instructing the model to emit a final <<expr>> span.
// We reserve ~72% of the total budget for the free reasoning preamble and the
// remainder for constrained span generation plus the closing delimiter.
// GenerateWithPrefixAndManagedSpan handles all span-state transitions, hard
// parser control inside the span, and the proof obligations for the managed
// loop. When maxSteps == 0 we return immediately with unchanged state and cost 0.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//   Base case (maxSteps == 0): we assign insideConstrainedOut := insideConstrained
//   and currentConstrainedOut := currentConstrained, which satisfy the precondition
//   directly. Else branch: GenerateWithPrefixAndManagedSpan's postcondition
//   guarantees (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)), so
//   the invariant is preserved by the helper's contract without any additional
//   caller-side proof.
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps  (with steps <= cost <= maxSteps)
//   Base case (maxSteps == 0): generated := generatedPrefix, so equality holds,
//   and cost := 0. Else branch: GenerateWithPrefixAndManagedSpan guarantees
//   |generatedOut| <= |generatedPrefix| + maxSteps. We set cost := maxSteps,
//   satisfying cost <= maxSteps. Because maxSteps > 0, cost > 0 also satisfies
//   the last postcondition disjunct even if generated == generatedPrefix.
//   Helpers that consume tokens without visible output growth (EOS, rejected
//   suffixes) still count against the token budget but cannot cause |generated|
//   to exceed the bound.
// CSD_PROOF_SKETCH_END

// Initialize all out-parameters before any branching
generated            := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost                 := 0;

if maxSteps == 0 {
  // No budget; return inputs unchanged with cost already 0
} else {
  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. At the very end, write your answer as <<expr>> " +
    "where expr uses only: variable names (no curly braces), integers, +, -, *, /, //, %, (, ), int(). " +
    "ALWAYS wrap integer results in int(). No LaTeX, no {braces}, no ** operator. " +
    "Keep the expression short. One <<expr>> at the very end only.");

  // Allocate ~72% of the budget to free-text reasoning; guard against overflow
  var prefixBudget: nat := (maxSteps * 72) / 100;
  if prefixBudget >= maxSteps {
    prefixBudget := maxSteps - 1;
  }

  var g, ic, cc := helpers.GenerateWithPrefixAndManagedSpan(
    lm, parser, prompt,
    generated, insideConstrainedOut, currentConstrainedOut,
    maxSteps, prefixBudget,
    validTokenGroups,
    10.0,
    6,
    eosToken
  );
  generated             := g;
  insideConstrainedOut  := ic;
  currentConstrainedOut := cc;

  cost := maxSteps;
}
